#[verifier::external_trait_specification]
pub trait ExRead {
    type ExternalTraitSpecificationFor: Read;

    fn read_to_string(&mut self, buf: &mut String) -> (result: std::io::Result<usize>)
        ensures
            old(buf)@.is_prefix_of(final(buf)@),
            result is Ok ==> encode_utf8(final(buf)@).len()
                == encode_utf8(old(buf)@).len() + (result->Ok_0) as nat,
    ;
}

#[verifier::external_trait_specification]
pub trait ExWrite {
    type ExternalTraitSpecificationFor: Write;

    fn write(&mut self, buf: &[u8]) -> (result: std::io::Result<usize>)
        ensures
            result is Ok ==> ((result->Ok_0) as nat) <= buf@.len(),
    ;
}
